// Resumen del dia anterior en formato largo (section, clave, valor).
const sql = `SELECT 'kpi' AS section, concat(kpi_name, '|', equipo) AS clave, avg(value) AS valor
FROM kpi_values
WHERE period = 'day'
  AND ts >= dateadd('d', -1, date_trunc('day', now()))
  AND ts <  date_trunc('day', now())
GROUP BY kpi_name, equipo
UNION ALL
SELECT 'evento' AS section, severity AS clave, cast(count(*) AS double) AS valor
FROM events
WHERE ts >= dateadd('d', -1, date_trunc('day', now()))
  AND ts <  date_trunc('day', now())
GROUP BY severity
UNION ALL
SELECT 'anomalia' AS section, event_type AS clave, cast(count(*) AS double) AS valor
FROM events
WHERE event_type = 'ANOMALY_ZSCORE'
  AND ts >= dateadd('d', -1, date_trunc('day', now()))
  AND ts <  date_trunc('day', now())
GROUP BY event_type`;

msg.method = 'GET';
msg.url = (env.get('QUESTDB_HTTP_URL') || 'http://localhost:9000') + '/exec?query=' + encodeURIComponent(sql);
msg.headers = {};
const token = env.get('QUESTDB_TOKEN');
if (token) msg.headers['Authorization'] = 'Bearer ' + token;
return msg;

const r = msg.payload || {};
const cols = (r.columns || []).map(c => c.name);
const rows = (r.dataset || []).map(row => {
    const o = {};
    cols.forEach((c, i) => { o[c] = row[i]; });
    return o;
});

const kpis = [];
const eventos = { info: 0, warning: 0, critical: 0 };
let anomalias = 0;

rows.forEach(o => {
    if (o.section === 'kpi') {
        const [kpi_name, equipo] = String(o.clave).split('|');
        kpis.push({ equipo, kpi_name, valor: (o.valor === null ? 'N/D' : Number(o.valor).toFixed(3)) });
    } else if (o.section === 'evento') {
        eventos[o.clave] = Number(o.valor) || 0;
    } else if (o.section === 'anomalia') {
        anomalias = Number(o.valor) || 0;
    }
});

kpis.sort((a, b) => (a.equipo + a.kpi_name).localeCompare(b.equipo + b.kpi_name));

const ayer = new Date(Date.now() - 86400000).toISOString().slice(0, 10);
msg.reporte = {
    fecha: ayer,
    kpis: kpis,
    total_kpis: kpis.length,
    ev_info: eventos.info || 0,
    ev_warning: eventos.warning || 0,
    ev_critical: eventos.critical || 0,
    anomalias: anomalias,
    generado: new Date().toISOString()
};
msg.topic = 'Reporte diario AquaMonitor - ' + ayer;
return msg;
